contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool p) public payable {
        // Drive c to a known paused/unpaused state using the public surface.
        // pause/unpause require PAUSER_ROLE; only attempt a call whose result
        // is observed via the paused() getter.
        if (p) {
            try c.pause() {} catch {}
        } else {
            try c.unpause() {} catch {}
        }

        bool pausedNow = c.paused();

        // With c paused, a state-changing entrypoint must revert.
        // deposit(msg.value=0) with an invalid token is a valid entry to probe;
        // but we only assert the general rule when pausedNow is true.
        bool reverted;
        try c.deposit(DepositParams({token: address(c), amount: 1, to: address(this)})) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(!pausedNow || reverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool doPause, bool doUnpause) public payable {
        // Only proceed when the caller (this test contract) holds PAUSER_ROLE,
        // which is granted to the owner passed at initialize time. Since the
        // checker deploys c with this test contract as owner, it does.
        require(c.hasRole(keccak256("PAUSER_ROLE"), address(this)), "no pauser role");

        uint256 beforePauseCalls = c.paused() ? 1 : 0;

        // Drive c through the public entry `paused` by toggling via pause().
        // A successful pause() must be observable through paused().
        if (doPause) {
            c.pause();
        }

        bool pausedAfterPossiblePause = c.paused();

        // If we actually paused, the getter must now report paused.
        // If we did not call pause, the getter must be unchanged relative
        // to the observed state at entry.
        assert(doPause ? pausedAfterPossiblePause : (pausedAfterPossiblePause == (beforePauseCalls == 1)));

        // Now show unpause() is the inverse observable transition, but only
        // through a second deciding call whose result we also read via paused().
        if (doUnpause) {
            c.unpause();
        }

        bool pausedAfterPossibleUnpause = c.paused();

        assert(doUnpause ? !pausedAfterPossibleUnpause : (pausedAfterPossibleUnpause == pausedAfterPossiblePause));
    }

    receive() external payable {}
}

contract InvMutTest {
