    constructor(C _c) {
        c = _c;
    }

    function run(uint256 op) public payable {
        bool pausedBefore = c.paused();

        if (op % 2 == 0) {
            try c.pause() {} catch {}
        } else {
            try c.unpause() {} catch {}
        }

        bool pausedAfter = c.paused();

        assert(pausedAfter == (op % 2 == 0 ? true : false));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool isPause) public payable {
        bool reverted;
        if (isPause) {
            try c.pause() { reverted = false; } catch { reverted = true; }
            bool pausedAfter = c.paused();
            assert(reverted || pausedAfter);
        } else {
            try c.unpause() { reverted = false; } catch { reverted = true; }
            bool pausedAfter = c.paused();
            assert(reverted || !pausedAfter);
        }
    }

    receive() external payable {}
}

