        bool reverted;
        if (isPause) {
            try c.pause() { reverted = false; } catch { reverted = true; }
            bool pausedAfter = c.paused();
            assert(reverted ? pausedAfter == pausedBefore : pausedAfter);
        } else {
            try c.unpause() { reverted = false; } catch { reverted = true; }
            bool pausedAfter = c.paused();
            assert(reverted ? pausedAfter == pausedBefore : !pausedAfter);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes4 interfaceId) public payable {
        bool reverted;
        bool result;
        try c.supportsInterface(interfaceId) returns (bool r) {
            reverted = false;
            result = r;
        } catch {
            reverted = true;
            result = false;
        }
        bool erc165 = interfaceId == bytes4(0x01ffc9a7);
        bool accessControl = interfaceId == bytes4(0x7965db0b);
        assert(!reverted && (erc165 || accessControl ? result : true));
    }
}

